select DISTINCT * from ( select * from ( select wtpdp.trade_id entrustId, '01' tradeType, '交易预录入' tradeTypeName, null entrustStatus, wtpdp.TRADE_DATE createTimeVal, tpdap.portfolio_id portfolioId, pp.portfolio_name portfolioName, wtpdp.finprod_type2 finprodType2, wtpdp.finprod_id finprodId, fp.FINPROD_MARKET_ID finprodMarketId, fp.FINPROD_ABBR finprodAbbr, wtpdp.ps ps, case when wtpdp.finprod_type2='F01' THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'PS' AND ITEM_CODE = wtpdp.ps) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'BACK_LEND_DIRECTION' AND ITEM_CODE = wtpdp.PS) END otherPs, wtpdp.trade_market tradeMarket, decode(wtpdp.settle_speed,0,'01',1,'02',2,'03') settleSpeed, null entrustAmt, wtpdp.prin_amt prinAmt, null tradeAmt, null proAvailableCash, null finshAmt, null percent, wtpdp.CHL_ID chlId, wtpdp.sec_manage_acct_id secAcctId, wtpdp.ccy ccy, wtpdp.trader trader, wtpdp.remark remark, wtpdp.vdate vdate, wtpdp.mdate mdate, wtpdp.unit_cprice price, wtpdp.yield matureYield, wtpdp.exer_yield exerYield, null priceMode, T1.REPO_TERM repoTerm from TRD_PRODUCT_DEAL_PRE wtpdp left join TRD_PRODUCT_DEAL_ADD_PRE tpdap on tpdap.trade_id = wtpdp.trade_id inner join PTL_PORTFOLIO pp ON pp.PORTFOLIO_ID = tpdap.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT fp ON fp.FINPROD_ID = wtpdp.FINPROD_ID left join TRD_FIN_PRODUCT_DEAL_TOTAL T1 on T1.TOTLE_TRADE_ID = wtpdp.TOTLE_TRADE_ID
